if (!fs.existsSync(INDEX)) { console.error("FATAL: wiki index.md missing"); process.exit(1); }
let content = fs.readFileSync(INDEX, "utf8");

// 1. Strip any prior block this script appended (self-correcting -- removes the
//    malformed ascii-hyphen entries from the first run). The block runs from the
//    marker comment to EOF (we always append at the end).
const markerIdx = content.indexOf(MARKER);
if (markerIdx !== -1) {
  // back up to the newline before the marker comment
  const nlBefore = content.lastIndexOf("\n", markerIdx);
  content = content.slice(0, nlBefore === -1 ? markerIdx : nlBefore);
}

// 2. Build correct em-dash-delimited entries.
const lines = ENTRIES.map(([slug, g, file, desc]) =>
  `- [[${slug}]] ${EM} ${desc} | category:architecture | sources:3 | confidence:0.85 | last_verified:2026-06-10 | source:${file}`
);
const block = `\n${MARKER} verify-promote + deepen + pass2-keyword-refresh, papa 2026-06-10; em-dash-delimited for wiki-precheck parser) -->\n` + lines.join("\n") + "\n";

if (DRY) {
  console.log(`[dry] would (re)write ${lines.length} foundations entries with em-dash separator (${block.length} bytes)`);
} else {
  fs.writeFileSync(INDEX, content.replace(/\s*$/, "\n") + block);
  console.log(`(re)wrote ${lines.length} foundations entries to wiki index (em-dash-delimited, pass-2 keywords)`);
}
